#!/bin/sh
# Install the Mixpost CLI from its GitHub releases.
#
#   curl -fsSL https://raw.githubusercontent.com/inovector/mixpost-cli/main/install.sh | sh
#
# Environment:
#   MIXPOST_VERSION      release to install, e.g. 0.2.0 or v0.2.0 (default: the latest)
#   MIXPOST_INSTALL_DIR  directory to install into (default: /usr/local/bin when
#                        writable, otherwise ~/.local/bin)

set -eu

REPO="inovector/mixpost-cli"
BINARY="mixpost"

say() { printf '%s\n' "$*" >&2; }
fail() { say "mixpost install: $*"; exit 1; }

need() {
	command -v "$1" >/dev/null 2>&1 || fail "$1 is required"
}

detect_os() {
	case "$(uname -s)" in
	Linux) echo linux ;;
	Darwin) echo darwin ;;
	MINGW* | MSYS* | CYGWIN*) fail "on Windows, install with 'scoop install mixpost' or download the zip from https://github.com/$REPO/releases" ;;
	*) fail "unsupported operating system: $(uname -s)" ;;
	esac
}

detect_arch() {
	case "$(uname -m)" in
	x86_64 | amd64) echo amd64 ;;
	aarch64 | arm64) echo arm64 ;;
	armv7l | armv7) echo armv7 ;;
	*) fail "unsupported architecture: $(uname -m)" ;;
	esac
}

latest_version() {
	# The latest release redirects to its tag, which avoids the rate-limited API.
	url=$(curl -fsSLI -o /dev/null -w '%{url_effective}' "https://github.com/$REPO/releases/latest") ||
		fail "could not reach GitHub to find the latest release"
	tag=${url##*/}
	case "$tag" in
	v*) echo "${tag#v}" ;;
	*) fail "no release has been published yet" ;;
	esac
}

sha256() {
	if command -v sha256sum >/dev/null 2>&1; then
		sha256sum "$1" | cut -d' ' -f1
	elif command -v shasum >/dev/null 2>&1; then
		shasum -a 256 "$1" | cut -d' ' -f1
	else
		fail "sha256sum or shasum is required to verify the download"
	fi
}

install_dir() {
	if [ -n "${MIXPOST_INSTALL_DIR:-}" ]; then
		echo "$MIXPOST_INSTALL_DIR"
	elif [ -w /usr/local/bin ]; then
		echo /usr/local/bin
	else
		echo "$HOME/.local/bin"
	fi
}

main() {
	need curl
	need tar
	need uname

	os=$(detect_os)
	arch=$(detect_arch)
	if [ "$os" = darwin ] && [ "$arch" = armv7 ]; then
		fail "unsupported architecture for macOS: armv7"
	fi

	version=${MIXPOST_VERSION:-}
	version=${version#v}
	[ -n "$version" ] || version=$(latest_version)

	archive="${BINARY}_${version}_${os}_${arch}.tar.gz"
	base="https://github.com/$REPO/releases/download/v$version"

	tmp=$(mktemp -d)
	trap 'rm -rf "$tmp"' EXIT INT TERM

	say "Downloading $BINARY $version for $os/$arch"
	curl -fsSL -o "$tmp/$archive" "$base/$archive" || fail "could not download $base/$archive"
	curl -fsSL -o "$tmp/checksums.txt" "$base/checksums.txt" || fail "could not download the checksums"

	expected=$(awk -v name="$archive" '$2 == name { print $1 }' "$tmp/checksums.txt")
	[ -n "$expected" ] || fail "$archive is not listed in checksums.txt"
	[ "$(sha256 "$tmp/$archive")" = "$expected" ] || fail "checksum mismatch for $archive"

	tar -xzf "$tmp/$archive" -C "$tmp" "$BINARY" || fail "could not unpack $archive"

	dir=$(install_dir)
	mkdir -p "$dir" || fail "could not create $dir"
	if [ -w "$dir" ]; then
		install -m 0755 "$tmp/$BINARY" "$dir/$BINARY"
	else
		say "Installing to $dir needs sudo"
		sudo install -m 0755 "$tmp/$BINARY" "$dir/$BINARY"
	fi

	say "Installed $dir/$BINARY"
	case ":$PATH:" in
	*":$dir:"*) ;;
	*) say "Add $dir to your PATH to run $BINARY from anywhere." ;;
	esac
	say "Next: mixpost auth login --personal-key <personal-key>"
}

main "$@"

package cli

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"os"
	"strings"

	"github.com/inovector/mixpost-cli/internal/config"
	"github.com/inovector/mixpost-cli/internal/mixpost"
	"github.com/inovector/mixpost-cli/internal/output"
	"github.com/spf13/cobra"
)

func newAuthCommand() *cobra.Command {
	cmd := &cobra.Command{
		Use:         "auth",
		Short:       "Manage credentials for one or more Mixpost instances",
		Annotations: map[string]string{skipClientAnnotation: "true"},
	}
	cmd.AddCommand(newAuthLoginCommand(), newAuthStatusCommand(), newAuthLogoutCommand())
	return cmd
}

func newAuthLoginCommand() *cobra.Command {
	var (
		urlFlag     string
		key         string
		keyStdin    bool
		workspace   string
		noVerify    bool
		profileName string
	)

	cmd := &cobra.Command{
		Use:   "login",
		Short: "Store the Mixpost address and personal key in a profile",
		Long: `Store credentials in a profile so later commands do not need them.

Without --url the profile uses Mixpost Cloud. For a self-hosted instance, pass
the address you open Mixpost at, including its core path, such as
https://example.com/mixpost. An address without a path is tried with the
default /mixpost core path first and at the site root second.

Create a personal key from the user menu: click API, then Create a personal
key. It is shown once, so copy it straight away.`,
		Example: `  mixpost auth login --personal-key <personal-key>
  mixpost auth login --url https://example.com/mixpost --personal-key <personal-key>
  echo "$MIXPOST_PERSONAL_KEY" | mixpost auth login --url https://example.com/mixpost --personal-key-stdin
  mixpost auth login --url https://staging.example.com/mixpost --personal-key <personal-key> --profile staging`,
		Args: cobra.NoArgs,
		RunE: func(cmd *cobra.Command, _ []string) error {
			if profileName == "" {
				profileName = env.Profile
			}

			cfg := env.Config
			profile := cfg.EnsureProfile(profileName)

			var candidates []string
			if urlFlag != "" {
				var err error
				if candidates, err = config.BaseURLCandidates(urlFlag); err != nil {
					return usageError(err)
				}
				profile.URL = candidates[0]
			}
			if profile.URL == "" {
				profile.URL = config.DefaultBaseURL
			}

			switch {
			case keyStdin:
				data, err := io.ReadAll(os.Stdin)
				if err != nil {
					return fmt.Errorf("read the personal key from stdin: %w", err)
				}
				profile.Key = strings.TrimSpace(string(data))
			case key != "":
				profile.Key = key
			case output.IsTTY(stdin) || profile.Key == "":
				// On a terminal, always ask: logging in again is how a stale
				// key gets replaced. Enter keeps the stored one.
				value, err := promptKey(ctxOf(cmd), env.Printer, profile.URL, profile.Key)
				if err != nil {
					return err
				}
				if value != "" {
					profile.Key = value
				}
			}
			if profile.Key == "" {
				return usageError(errors.New("no personal key provided"))
			}
			if workspace != "" {
				profile.Workspace = workspace
			}

			if cfg.CurrentProfile == "" {
				cfg.CurrentProfile = profileName
			}

			if !noVerify {
				if len(candidates) > 1 {
					profile.URL = pickBaseURL(cmd, profile, candidates)
				}
				if err := verifyProfile(cmd, profile); err != nil {
					return err
				}
			}
			if err := cfg.Save(); err != nil {
				return err
			}

			env.Printer.PrintMessage("Saved profile %q to %s", profileName, cfg.FilePath())
			if profile.Workspace == "" {
				env.Printer.PrintMessage("No workspace set. Run 'mixpost workspace list', then 'mixpost config set workspace <uuid>'.")
			}
			return env.RenderRaw(profileSummary(profileName, profile, true), authColumns())
		},
	}

	f := cmd.Flags()
	f.StringVar(&urlFlag, "url", "", "self-hosted Mixpost address, e.g. https://example.com/mixpost (default: Mixpost Cloud)")
	f.StringVar(&key, "personal-key", "", "personal key")
	f.BoolVar(&keyStdin, "personal-key-stdin", false, "read the personal key from stdin")
	f.StringVar(&workspace, "workspace", "", "default workspace UUID for this profile")
	f.StringVar(&profileName, "profile", "", "profile to write (default: the active profile)")
	f.BoolVar(&noVerify, "no-verify", false, "skip the connectivity check")
	return cmd
}

// pickBaseURL returns the first candidate base URL that serves the Mixpost
// API, judged by whether the workspace listing answers with anything but 404. When none does, the first candidate stays, and verification reports why.
func pickBaseURL(cmd *cobra.Command, profile *config.Profile, candidates []string) string {
	for i, candidate := range candidates {
		probe := *profile
		probe.URL = candidate
		_, err := profileClient(&probe).Workspaces(ctxOf(cmd))
		var apiErr *mixpost.APIError
		if err == nil || (errors.As(err, &apiErr) && apiErr.Status != 404) {
			if i > 0 {
				env.Printer.PrintMessage("No Mixpost API under %s; using %s.", candidates[0], candidate)
			}
			return candidate
		}
	}
	return candidates[0]
}

func profileClient(profile *config.Profile) *mixpost.Client {
	return mixpost.New(mixpost.Options{
		BaseURL:   profile.BaseURL(),
		Key:       profile.Key,
		Workspace: profile.Workspace,
		Timeout:   flags.timeout,
		Retries:   flags.retries,
		Insecure:  flags.insecure,
		UserAgent: userAgent(),
		Debug:     flags.debug,
		DebugOut:  env.Printer.Err,
	})
}

// verifyProfile makes one cheap authenticated call so a typo in the URL or the
// key surfaces at login instead of at the first real command.
func verifyProfile(cmd *cobra.Command, profile *config.Profile) error {
	client := profileClient(profile)
	ctx := ctxOf(cmd)
	if profile.Workspace != "" {
		if _, err := client.Get(ctx, "accounts", nil); err != nil {
			return fmt.Errorf("could not reach the workspace with these credentials: %w", err)
		}
		return nil
	}

	// With no workspace to address, list the workspaces: it needs none and
	// every edition serves it, unlike ping.
	if _, err := client.Workspaces(ctx); err != nil {
		return fmt.Errorf("could not reach Mixpost with these credentials: %w", err)
	}
	return nil
}

// promptKey reads a personal key from the terminal without echoing it,
// after saying where to create one. current is the stored key, which an empty
// answer keeps.
func promptKey(ctx context.Context, printer *output.Printer, baseURL, current string) (string, error) {
	if !output.IsTTY(stdin) {
		return "", usageError(fmt.Errorf("pass a personal key with --personal-key, or pipe it in with --personal-key-stdin; create one at %s", keysPage(baseURL)))
	}
	printer.PrintMessage("Open this page and click Create a personal key:\n\n  %s\n", output.Hyperlink(printer.Err, keysPage(baseURL)))
	if current != "" {
		fmt.Fprintf(printer.Err, "Personal key (Enter keeps %s): ", mixpost.Redact(current))
	} else {
		fmt.Fprint(printer.Err, "Personal key: ")
	}
	return readTerminal(ctx, printer.Err, true)
}

// keysPage is the dashboard page that lists and creates personal keys.
func keysPage(baseURL string) string {
	return baseURL + "/profile/api"
}

func newAuthStatusCommand() *cobra.Command {
	var checkAll bool

	cmd := &cobra.Command{
		Use:   "status",
		Short: "Show the active profile and check that it works",
		Args:  cobra.NoArgs,
		RunE: func(cmd *cobra.Command, _ []string) error {
			cfg := env.Config
			names := []string{env.Profile}
			if checkAll {
				names = cfg.ProfileNames()
			}
			if len(names) == 0 {
				return usageError(errors.New("no profiles configured; run 'mixpost auth login'"))
			}

			rows := make([]map[string]any, 0, len(names))
			failed := false
			for _, name := range names {
				profile := cfg.Profile(name)
				if profile == nil {
					rows = append(rows, map[string]any{
						"profile": name, "authenticated": false, "error": "profile not configured",
					})
					failed = true
					continue
				}
				row := map[string]any{
					"profile":      name,
					"url":          profile.BaseURL(),
					"personal_key": mixpost.Redact(profile.Key),
					"workspace":    profile.Workspace,
					"active":       name == env.Profile,
				}
				if err := verifyProfile(cmd, profile); err != nil {
					row["authenticated"] = false
					row["error"] = err.Error()
					failed = true
				} else {
					row["authenticated"] = true
				}
				rows = append(rows, row)
			}

			raw, err := json.Marshal(map[string]any{"data": rows})
			if err != nil {
				return err
			}
			if err := env.RenderRaw(raw, authColumns()); err != nil {
				return err
			}
			if failed {
				return errors.New("at least one profile could not authenticate")
			}
			return nil
		},
	}
	cmd.Flags().BoolVar(&checkAll, "all", false, "check every configured profile")
	return cmd
}

func newAuthLogoutCommand() *cobra.Command {
	var profileName string

	cmd := &cobra.Command{
		Use:   "logout",
		Short: "Remove a profile and its stored personal key",
		Args:  cobra.NoArgs,
		RunE: func(cmd *cobra.Command, _ []string) error {
			if profileName == "" {
				profileName = env.Profile
			}
			cfg := env.Config
			if cfg.Profile(profileName) == nil {
				return usageError(fmt.Errorf("profile %q is not configured", profileName))
			}
			if err := env.Confirm(fmt.Sprintf("Remove profile %q and its stored personal key?", profileName)); err != nil {
				return err
			}

			delete(cfg.Profiles, profileName)
			if cfg.CurrentProfile == profileName {
				cfg.CurrentProfile = ""
				if names := cfg.ProfileNames(); len(names) > 0 {
					cfg.CurrentProfile = names[0]
				}
			}
			if err := cfg.Save(); err != nil {
				return err
			}
			env.Printer.PrintMessage("Removed profile %q.", profileName)
			return nil
		},
	}
	cmd.Flags().StringVar(&profileName, "profile", "", "profile to remove (default: the active profile)")
	return cmd
}

func profileSummary(name string, profile *config.Profile, authenticated bool) []byte {
	raw, _ := json.Marshal(map[string]any{"data": []map[string]any{{
		"profile":       name,
		"url":           profile.BaseURL(),
		"personal_key":  mixpost.Redact(profile.Key),
		"workspace":     profile.Workspace,
		"active":        true,
		"authenticated": authenticated,
	}}})
	return raw
}

func authColumns() []output.Column {
	return []output.Column{
		{Header: "profile", Path: "profile"},
		{Header: "url", Path: "url", MaxWidth: 50},
		{Header: "workspace", Path: "workspace"},
		{Header: "personal key", Path: "personal_key"},
		{Header: "authenticated", Path: "authenticated"},
	}
}

package mixpost

import (
	"context"
	"encoding/json"
	"fmt"
	"net/http"
	"net/url"
)

// Call is the shorthand used by most commands.
func (c *Client) Call(ctx context.Context, method, path string, query url.Values, body any) (*Response, error) {
	return c.Do(ctx, Request{Method: method, Path: path, Query: query, Body: body})
}

// Get performs a GET on a workspace-scoped or instance-level path.
func (c *Client) Get(ctx context.Context, path string, query url.Values) (*Response, error) {
	return c.Call(ctx, http.MethodGet, path, query, nil)
}

// Page is one page of a Laravel paginated collection.
type Page struct {
	Data  []json.RawMessage `json:"data"`
	Links struct {
		Next string `json:"next"`
	} `json:"links"`
	Meta json.RawMessage `json:"meta"`
}

// Paginate walks every page of a collection, following links.next, and returns
// a single {"data": [...], "meta": {...}} document. A limit of 0 means "all".
func (c *Client) Paginate(ctx context.Context, path string, query url.Values, limit int) ([]byte, error) {
	var (
		all       []json.RawMessage
		firstMeta json.RawMessage
		pages     int
		next      string
	)

	for {
		var req Request
		if next == "" {
			req = Request{Method: http.MethodGet, Path: path, Query: query}
		} else {
			req = Request{Method: http.MethodGet, AbsoluteURL: next}
		}

		resp, err := c.Do(ctx, req)
		if err != nil {
			return nil, err
		}

		var page Page
		if err := json.Unmarshal(resp.Body, &page); err != nil {
			// Not a paginated collection; hand the payload back untouched.
			if pages == 0 {
				return resp.Body, nil
			}
			return nil, fmt.Errorf("decode page %d: %w", pages+1, err)
		}
		pages++
		if firstMeta == nil {
			firstMeta = page.Meta
		}

		for _, item := range page.Data {
			all = append(all, item)
			if limit > 0 && len(all) >= limit {
				return buildCollection(all, firstMeta, pages)
			}
		}

		if page.Links.Next == "" {
			break
		}
		next = page.Links.Next
	}

	return buildCollection(all, firstMeta, pages)
}

func buildCollection(items []json.RawMessage, firstMeta json.RawMessage, pages int) ([]byte, error) {
	if items == nil {
		items = []json.RawMessage{}
	}
	meta := map[string]any{"fetched": len(items), "pages": pages}
	if len(firstMeta) > 0 {
		var m map[string]any
		if err := json.Unmarshal(firstMeta, &m); err == nil {
			if total, ok := m["total"]; ok {
				meta["total"] = total
			}
		}
	}
	return json.Marshal(map[string]any{"data": items, "meta": meta})
}

// DecodeInto unmarshals a response body into v.
func (r *Response) DecodeInto(v any) error {
	if len(r.Body) == 0 {
		return nil
	}
	return json.Unmarshal(r.Body, v)
}

// Account is the subset of an account the CLI resolves names against.
type Account struct {
	ID       int    `json:"id"`
	UUID     string `json:"uuid"`
	Name     string `json:"name"`
	Username string `json:"username"`
	Provider string `json:"provider"`
}

// Accounts lists the social accounts in the current workspace.
func (c *Client) Accounts(ctx context.Context) ([]Account, error) {
	resp, err := c.Get(ctx, "accounts", nil)
	if err != nil {
		return nil, err
	}
	var payload struct {
		Data []Account `json:"data"`
	}
	if err := resp.DecodeInto(&payload); err != nil {
		return nil, fmt.Errorf("decode accounts: %w", err)
	}
	return payload.Data, nil
}

// Tag is the subset of a tag the CLI resolves names against.
type Tag struct {
	ID       int    `json:"id"`
	UUID     string `json:"uuid"`
	Name     string `json:"name"`
	HexColor string `json:"hex_color"`
}

// Tags lists the tags in the current workspace.
func (c *Client) Tags(ctx context.Context) ([]Tag, error) {
	resp, err := c.Get(ctx, "tags", nil)
	if err != nil {
		return nil, err
	}
	var payload struct {
		Data []Tag `json:"data"`
	}
	if err := resp.DecodeInto(&payload); err != nil {
		return nil, fmt.Errorf("decode tags: %w", err)
	}
	return payload.Data, nil
}

// CreateTag creates a tag and returns it.
func (c *Client) CreateTag(ctx context.Context, name, hexColor string) (*Tag, error) {
	resp, err := c.Call(ctx, http.MethodPost, "tags", nil, map[string]any{
		"name": name, "hex_color": hexColor,
	})
	if err != nil {
		return nil, err
	}
	var tag Tag
	if err := resp.DecodeInto(&tag); err != nil {
		return nil, fmt.Errorf("decode tag: %w", err)
	}
	return &tag, nil
}

// Workspace is a workspace the token's owner belongs to, as returned by
// GET /workspaces.
type Workspace struct {
	ID    int    `json:"id"`
	UUID  string `json:"uuid"`
	Name  string `json:"name"`
	Pivot struct {
		Role       string `json:"role"`
		CanApprove bool   `json:"can_approve"`
		JoinedAt   string `json:"joined_at"`
	} `json:"pivot"`
}

// Workspaces lists the workspaces the token can reach. The endpoint is
// instance-level, so it works before any workspace has been chosen.
func (c *Client) Workspaces(ctx context.Context) ([]Workspace, error) {
	resp, err := c.Do(ctx, Request{Method: http.MethodGet, Path: "workspaces", Instance: true})
	if err != nil {
		return nil, err
	}
	var payload struct {
		Data []Workspace `json:"data"`
	}
	if err := resp.DecodeInto(&payload); err != nil {
		return nil, fmt.Errorf("decode workspaces: %w", err)
	}
	return payload.Data, nil
}

